const segmentsById = new Map(SEGMENTS.map((segment) => [segment.id, segment]));

export function segmentById(id) {
  return segmentsById.get(id) ?? null;
}

// R4: street name and cross streets for a segment, derived from its id.
export function streetNamesFor(id) {
  const segment = segmentsById.get(id);
  if (!segment) return null;
  return { street: segment.street, crossFrom: segment.crossFrom, crossTo: segment.crossTo };
}

